WITH customer_info AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status, cd.cd_purchase_estimate, cd.cd_credit_rating, cd.cd_dep_count, cd.cd_dep_employed_count, cd.cd_dep_college_count, ca.ca_city, ca.ca_state FROM customer c JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk JOIN customer_address ca ON c.c_current_addr_sk = ca.ca_address_sk ), sales_data AS ( SELECT ws.ws_bill_customer_sk, SUM(ws.ws_sales_price) AS total_sales, COUNT(ws.ws_order_number) AS order_count, SUM(ws.ws_quantity) AS total_quantity FROM web_sales ws GROUP BY ws.ws_bill_customer_sk ), customer_sales AS ( SELECT ci.c_customer_sk, ci.c_first_name, ci.c_last_name, ci.cd_gender, ci.cd_marital_status, ci.cd_education_status, ci.cd_purchase_estimate, ci.cd_credit_rating, ci.cd_dep_count, ci.cd_dep_employed_count, ci.cd_dep_college_count, ci.ca_city, ci.ca_state, COALESCE(sd.total_sales, 0) AS total_sales, COALESCE(sd.order_count, 0) AS order_count, COALESCE(sd.total_quantity, 0) AS total_quantity FROM customer_info ci LEFT JOIN sales_data sd ON ci.c_customer_sk = sd.ws_bill_customer_sk ) SELECT cs.c_customer_sk, cs.c_first_name, cs.c_last_name, cs.cd_gender, SUM(cs.total_sales) AS total_spent, AVG(cs.total_quantity) AS average_quantity_per_order, COUNT(cs.order_count) AS total_orders FROM customer_sales cs WHERE cs.cd_gender = 'F' AND cs.cd_purchase_estimate > 1000 GROUP BY cs.c_customer_sk, cs.c_first_name, cs.c_last_name, cs.cd_gender HAVING SUM(cs.total_sales) > 5000 ORDER BY total_spent DESC LIMIT 10;

